mockup.css:
.mock-hero-quiet-fold { background: #faf9f6; color: #1a1917; font-family: "Inter", ui-sans-serif, sans-serif;
  display: flex; flex-direction: column; justify-content: flex-end; padding: 0 6cqw 4.5cqw; }
.mock-hero-quiet-fold .fold { width: 100%; }
.mock-hero-quiet-fold h4 { margin: 0 0 2.6cqw; font-size: 4.6cqw; font-weight: 400; line-height: 1.12;
  letter-spacing: -.02em; max-width: 58%; }
.mock-hero-quiet-fold .line { block-size: 1px; background: #1a1917; opacity: .22; }
.mock-hero-quiet-fold .base { display: flex; justify-content: space-between; align-items: baseline;
  margin-top: 3cqw; font-size: 1.6cqw; letter-spacing: .14em; text-transform: uppercase; opacity: .55; }
